style.css:
@-moz-document domain("example.com") {
:root{
    --bg: #120019;
    --bg2: #210028;

    --card: rgba(28, 0, 42, .65);

    --accent: #ff3dbd;
    --accent2: #b13dff;

    --text: #f5dfff;
    --muted: #cfa7e8;

    --border: rgba(255, 61, 189, .25);

    /* PUT YOUR IMAGE HERE */
    --bg-image: url("https://medibang.com/picture/hy2107090021010850016390247/");
}

/* ===== Background ===== */

html,
body{

    background:
        linear-gradient(
            rgba(18,0,25,.75),
            rgba(33,0,40,.8)
        ),

        var(--bg-image)

        center center / cover
        fixed
        no-repeat !important;

    color: var(--text) !important;

    font-family:
        Inter,
        Segoe UI,
        sans-serif !important;
}


/* ===== Frosted Glass ===== */

main,
section,
article,
div[class*="card"],
div[class*="panel"],
div[class*="container"],
header,
footer,
nav{

    background: var(--card) !important;

    backdrop-filter: blur(18px);

    border: 1px solid var(--border) !important;

    border-radius: 18px;

    box-shadow:

        0 0 25px rgba(177,61,255,.12),

        0 0 45px rgba(255,61,189,.08);

}


/* ===== Text ===== */

h1,h2,h3,h4,h5,h6{

    color: #ffd9ff !important;

    text-shadow:

        0 0 12px rgba(255,61,189,.45);

}


p,
span,
li{

    color: var(--text) !important;

}


small,
time{

    color: var(--muted) !important;

}


/* ===== Links ===== */

a{

    color: var(--accent) !important;

    transition: .25s;

}


a:hover{

    color: #ff8ee1 !important;

    text-shadow:

        0 0 12px #ff3dbd,

        0 0 20px #ff3dbd;

}


/* ===== Buttons ===== */

button,

input[type="submit"],

input[type="button"]{

    background:

        linear-gradient(
        135deg,
        var(--accent),
        var(--accent2)
        ) !important;

    color:white !important;

    border:none !important;

    border-radius:14px;

    padding:10px 18px;

    box-shadow:

        0 0 15px rgba(255,61,189,.4);

    transition:.3s;

}


button:hover,

input[type="submit"]:hover,

input[type="button"]:hover{

    transform:translateY(-2px);

    box-shadow:

        0 0 20px rgba(255,61,189,.8),

        0 0 40px rgba(177,61,255,.5);

}


/* ===== Inputs ===== */

input,

textarea,

select{

    background:

        rgba(15,0,25,.7)

        !important;

    color:

        var(--text)

        !important;

    border:

        1px solid

        rgba(255,61,189,.25)

        !important;

    border-radius:12px;

}


input:focus,

textarea:focus{

    outline:none;

    border:

        1px solid

        var(--accent)

        !important;

    box-shadow:

        0 0 20px

        rgba(255,61,189,.45);

}


/* ===== Scrollbar ===== */

::-webkit-scrollbar{

    width:12px;

}


::-webkit-scrollbar-track{

    background:#120019;

}


::-webkit-scrollbar-thumb{

    background:

        linear-gradient(

        var(--accent),

        var(--accent2)

        );

    border-radius:999px;

}


::-webkit-scrollbar-thumb:hover{

    box-shadow:

        0 0 15px #ff3dbd;

}


/* ===== Selection ===== */

::selection{

    background:

        rgba(255,61,189,.4);

    color:white;

}
}
